int main(void){@autoreleasepool{if(!dlopen("/System/Library/PrivateFrameworks/PreviewShellKit.framework/Versions/A/PreviewShellKit",RTLD_NOW|RTLD_LOCAL))return 2;NSMutableDictionary *out=[NSMutableDictionary dictionary];for(NSString *name in @[@"FBLocalSynchronousSceneClientProvider"]){Class c=NSClassFromString(name);if(!c){out[name]=@[];continue;}NSMutableArray *rows=[NSMutableArray array];for(Class k=c;k&&k!=[NSObject class];k=class_getSuperclass(k)){unsigned n=0;Method *m=class_copyMethodList(k,&n);for(unsigned i=0;i<n;i++){NSString *sel=NSStringFromSelector(method_getName(m[i]));[rows addObject:@{@"owner":@(class_getName(k)),@"selector":sel,@"types":@(method_getTypeEncoding(m[i])),@"address":[NSString stringWithFormat:@"0x%llx",(unsigned long long)method_getImplementation(m[i])]}];}free(m);}out[name]=rows;}NSData *d=[NSJSONSerialization dataWithJSONObject:out options:NSJSONWritingPrettyPrinted error:NULL];fwrite(d.bytes,1,d.length,stdout);puts("");return 0;}}
